import unittest
from cleaning import normalize_spaces
class CleaningTests(unittest.TestCase):
    def test_spaces(self):
        self.assertEqual(normalize_spaces('  one   two  '), 'one two')

    def test_mixed_whitespace(self):
        self.assertEqual(normalize_spaces('\t one\n\n two \r\t'), 'one two')

    def test_only_whitespace(self):
        self.assertEqual(normalize_spaces(' \t\n '), '')
